 useEffect(()=>{if(!game)return;setSaved('Đang lưu ván…');const snap=structuredClone(game);saveQueue.current=saveQueue.current.catch(()=>{}).then(()=>localSet(gameKey,snap)).then(()=>{setSaved('Ván đã lưu trên máy này');}).catch(()=>{setSaved('Lỗi lưu ván. Hãy xuất kết quả trước khi đóng.');});},[game]);
