 const quizzes=[demo,...(data?.quizzes??[]).filter(q=>view==='trash'?!!q.deletedAt:!q.deletedAt)].filter(q=>(view!=='trash'||q.id!=='demo')&&(!folder||q.folderId===folder)&&(!search||[q.title,q.description,...q.questions.map(x=>x.topic)].join(' ').toLowerCase().includes(search.toLowerCase())));
