 {view==='trash'&&data?.folders.filter(f=>f.deletedAt).map(f=><div className="trash-folder" key={f.id}><FolderOpen size={19}/><span>{f.name}</span><button className="button" onClick={()=>mutate({action:'folderRestore',id:f.id}).catch(()=>{})}>Khôi phục thư mục</button></div>)}
